def sha(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(1024*1024),b''):h.update(b)
 return h.hexdigest()
def main():
 records=[json.loads(l) for f in ROOT.glob('main-worker-*.jsonl') for l in f.open()];records.sort(key=lambda r:r['case_id']);assert len(records)==20000 and [r['case_id'] for r in records]==list(range(20000));assert all(r['status']=='pass' for r in records)
 for r in records:
  cid=r['case_id'];i=cid%1000;assert r['mission']==MISSIONS[cid//1000] and r['config']==params(i);assert r['sql_sha256']==hashlib.sha256(query(i).encode()).hexdigest()
 start=json.loads((ROOT/'main-start.json').read_text());assert start['code']=={n:sha(ROOT/n) for n in start['code']}
 with (ROOT/'cases.jsonl').open('w') as f:
  for r in records:f.write(json.dumps(r,separators=(',',':'))+'\n')
 with (ROOT/'cases.csv').open('w',newline='') as f:
  cols=['case_id','architecture','task','client','seconds','epochs','best_epoch','model_bytes','numpy_max_abs_error','test_rmse','test_accuracy','reconstruction_rmse','model_sha256'];w=csv.DictWriter(f,fieldnames=cols);w.writeheader()
  for r in records:w.writerow(dict(case_id=r['case_id'],architecture=r['mission']['architecture'],task=r['mission']['task'],client=r['client'],seconds=r['seconds'],epochs=r['training']['epochs'],best_epoch=r['training']['best_epoch'],model_bytes=r['model']['bytes'],numpy_max_abs_error=r['independent_numpy_max_abs_error'],test_rmse=r['metrics'].get('rmse'),test_accuracy=r['metrics'].get('accuracy'),reconstruction_rmse=r['metrics'].get('reconstruction_rmse'),model_sha256=r['model']['sha256']))
 registry=json.loads((ROOT/'preprocessing.json').read_text());missing=[]
 for r in records:
  f=ROOT/'models'/f"{r['case_id']:05d}.pt"
  if not f.exists() or sha(f)!=r['model']['sha256']:missing.append(r['case_id'])
  saved=registry[str(r['config']['i'])]
  for name,key in [('mu','mu'),('sd','sd'),('target_mu','ym'),('target_sd','ys')]:assert r['preprocessing'][name]==saved[key]
 assert not missing,missing[:10]
 # All 20k exact model binaries are retained and hashed, not only sample models.
 env=json.loads((ROOT/'environment.json').read_text());state=json.loads((ROOT/'final-state.json').read_text());mainmeta=json.loads((ROOT/'main-summary.json').read_text());spark=json.loads((ROOT/'spark-summary.json').read_text());compound=json.loads((ROOT/'compound-summary.json').read_text());perf=json.loads((ROOT/'performance-summary.json').read_text())
 missions=[]
 for desc in MISSIONS:
  rs=[r for r in records if r['mission']['id']==desc['id']];lat=np.array([r['seconds'] for r in rs]);train=np.array([r['timing']['train'] for r in rs]);m=dict(**desc,cases=len(rs),passed=len(rs),median_seconds=float(np.median(lat)),p95_seconds=float(np.quantile(lat,.95)),actual_train_median_seconds=float(np.median(train)),initial_checkpoint_selected=sum(r['training']['best_epoch']==0 for r in rs),mean_test_metrics={})
  for key in rs[0]['metrics']:m['mean_test_metrics'][key]=float(np.mean([r['metrics'][key] for r in rs]))
  if 'baseline_rmse' in rs[0]['metrics']:m['forecast_beats_baseline']=sum(r['metrics']['rmse']<r['metrics']['baseline_rmse'] for r in rs)
  missions.append(m)
 q=query(443);complexity=dict(source_tables=16,join_keywords=len(re.findall(r'\bJOIN\b',q,re.I)),select_keywords=len(re.findall(r'\bSELECT\b',q,re.I)),exists_keywords=len(re.findall(r'\bEXISTS\b',q,re.I)),bytes=len(q.encode()),interpretation='SQL text keyword counts, not executed physical operator counts; 1000 distinct feature SQL shared by 20 different model/task pipelines, but every main case executes a fresh MO read.')
 index=[dict(id=r['case_id'],arch=r['mission']['architecture'],task=r['mission']['task'],client=r['client'],i=r['config']['i'],config=r['config'],s=r['seconds'],bytes=r['model']['bytes'],np_error=r['independent_numpy_max_abs_error'],best=r['training']['best_epoch'],history=r['training']['history'],metrics=r['metrics'],sha=r['model']['sha256'],test_ids=r['test_entity_ids'],predictions=r['test_predictions'],anchors=[r['train_anchor'],r['validation_anchor'],r['test_anchor']]) for r in records]
 (ROOT/'case-index.json').write_text(json.dumps(index,separators=(',',':')))
 report=dict(main=mainmeta,spark=spark,compound=compound,performance=perf,environment=env,stability=state,complexity=complexity,missions=missions,total_compatibility_workflows=20000+spark['passed']+compound['passed'],training_epochs=sum(r['training']['epochs'] for r in records),actual_optimizer_steps=sum(r['training']['steps'] for r in records),source_fact_rows_checked=sum(r['fact_rows'] for r in records),model_bytes_written_read_verified=sum(r['model']['bytes'] for r in records),holdout_prediction_rows_verified=20000*12,commits=sum(r['model']['transaction']=='commit' for r in records),rollbacks=sum(r['model']['transaction']=='rollback' for r in records),numpy_inference_max_abs_error=max(r['independent_numpy_max_abs_error'] for r in records),validation_initial_checkpoint_selected=sum(r['training']['best_epoch']==0 for r in records),model_binary_hash_verified=20000,
  methodology=['Deterministic synthetic 16-table dataset with 320 entities and 80 days, including sparse events, multiple trades/day, interventions, as-of maintenance, missing readings and noisy/anomalous signals.','40 training / 12 validation / 12 test entities are disjoint. Training label time is earlier than validation feature anchor; validation label time is earlier than test feature anchor.','Only declared 18 feature columns enter the networks; future labels/clean targets are used solely as supervision/evaluation. Denoising is supervised against known synthetic clean signals, not an unsupervised anomaly detector.','Raw full 29-column facts compared at rtol=atol=1e-8 BEFORE float32 training-input conversion. Train-only median imputation, scaling, target normalization, graph split isolation and test-label perturbation checks.','CPU networks have 2-5 configured blocks/layers, width 8-20, length 6-12, 8-14 epochs, varying batch size, horizon, optimizer learning rate/L2, gradient clipping, noise and missingness.','MO-fed actual and independently assembled native-pandas reference features undergo separate deterministic PyTorch fits with exact weight/output equality. Network algorithms are shared for this comparison.','Separately implemented NumPy forward passes for all 5 architectures compared to PyTorch at rtol=atol=3e-5 (float32-versus-float64 arithmetic). Every raw feature and trained weight is checked separately.','Validation selects the checkpoint and classification threshold/conformal residual quantile. Test targets never select checkpoints; cases selecting initial weights are reported explicitly. Finite gradients, nonzero optimizer updates and training loss decrease required.','Each model state and all 12 holdout predictions written to MO, read in full, reloaded with weights_only=True, and required to reproduce bit-exact inference. Alternate commit/rollback externally checked with another connection, followed by cleanup.','Spark loads and fully verifies all 16 source tables via JDBC, computes equivalent native Spark SQL, also pushes 10 feature SQL directly through MO JDBC, fits 20 native scaler/PCA/linear or logistic pipelines on training entities, and trains 200 deep models inside Python workers. Actual worker model blobs and full predictions go through Spark JDBC.','100 separate hybrid models join CNN, GRU, attention, graph and multi-head prediction, quantile forecast and masked reconstruction, with MC dropout, integrated gradients and bounded PGD. These checks establish consistency/finite outputs/bounds, not certified robustness or attribution completeness.','External PyTorch/Spark perform training. MO is evaluated as the data/feature/model/serving store. Compact synthetic CPU workloads do not establish production accuracy, GPU scaling or large-model performance.','140 pilot cases and the interrupted 1079-case scheduling attempt are excluded from the final 20000. An initial Spark worker-environment startup failure was archived and excluded; the full 200-case Spark batch reran with PYSPARK_PYTHON fixed to the test virtual environment. Execution sources frozen and checked; all 20000 canonical model artifacts hashed.'],known_issues=[dict(issue=29838,url='https://github.com/matrixorigin/matrixone/issues/29838',scope='Spark default JDBC isolation remains a known compatibility limitation; this batch explicitly uses READ_COMMITTED.'),dict(issue=29809,url='https://github.com/matrixorigin/matrixone/issues/29809',scope='Internal statement_info TEXT 65535 capacity issue can coexist with passing user workflows. This window includes old-file retries; logs alone do not prove permanent loss or recovery.'),dict(issue=29797,url='https://github.com/matrixorigin/matrixone/issues/29797',scope='Related statement trace capacity issue.')])
 report['serving_replay']=json.loads((ROOT/'serving-summary.json').read_text());report['resource_guards']={n:json.loads((ROOT/(n+'-guard.json')).read_text()) for n in ['spark','compound','serving_check','performance']};report['telemetry']=json.loads((ROOT/'telemetry-analysis.json').read_text());report['client_layout_finding']=json.loads((ROOT/'serving-layout-finding.json').read_text());report['github_issue_status']=json.loads((ROOT/'github-known-issue-status.json').read_text());report['frontend_issue_search']=json.loads((ROOT/'github-frontend-search.json').read_text());report['join_dependency_issue_search']=json.loads((ROOT/'github-join-dependency-search.json').read_text());report['methodology'].append('All 20000 exact models subsequently replayed on 1000 freshly read MO feature datasets, using saved preprocessing without refitting and with ALL outcome columns stripped before inference; bit-exact full predictions and independent NumPy verified again. C-contiguous float32 input layout fixed a preliminary client replay discrepancy of 4.3e-7, without widening tolerances. Validation residual interval coverage is measured empirically; temporal/domain shift does not assume exchangeability or guarantee nominal coverage.')
 (ROOT/'report.json').write_text(json.dumps(report,indent=2));(ROOT/'complexity.json').write_text(json.dumps(complexity,indent=2))
 page=HTML.replace('__DATA__',json.dumps(index,separators=(',',':')).replace('</','<\\/')).replace('__REPORT__',json.dumps(report,separators=(',',':')).replace('</','<\\/'))
 page=page.replace('src="performance.png"','src="data:image/png;base64,'+base64.b64encode((ROOT/'performance.png').read_bytes()).decode()+'"');(ROOT/'report.html').write_text(page)
